16	/**
17	 * Creates the Svelte image plugin which provides the preprocessor.
18	 * @param {import('vite').Plugin} imagetools_plugin
19	 * @returns {import('vite').Plugin}
20	 */
21	function image_plugin(imagetools_plugin) {
22		/**
23		 * @type {{
24		 *   plugin_context: import('vite').Rollup.PluginContext
25		 *   vite_config: import('vite').ResolvedConfig
26		 *   imagetools_plugin: import('vite').Plugin
27		 * }}
28		 */
29		const opts = {
30			// @ts-expect-error populated when build starts so we cheat on type
31			plugin_context: undefined,
32			// @ts-expect-error populated when build starts so we cheat on type
33			vite_config: undefined,
34			imagetools_plugin
35		};
36		const preprocessor = image(opts);
37	
38		return {
39			name: 'vite-plugin-enhanced-img',
40			api: {
41				sveltePreprocess: preprocessor
42			},
43			configResolved(config) {
44				opts.vite_config = config;
45			},
46			buildStart() {
47				opts.plugin_context = this;
48			}
49		};
50	}
