53	const fallback = {
54		'.avif': 'png',
55		'.gif': 'gif',
56		'.heif': 'jpg',
57		'.jpeg': 'jpg',
58		'.jpg': 'jpg',
59		'.png': 'png',
60		'.tiff': 'jpg',
61		'.webp': 'png'
62	};
