172	/**
173	 * @param {string} resolved_id
174	 * @param {{
175	 *   plugin_context: import('vite').Rollup.PluginContext
176	 *   imagetools_plugin: import('vite').Plugin
177	 * }} opts
178	 * @returns {Promise<import('vite-imagetools').Picture>}
179	 */
180	async function process(resolved_id, opts) {
181		if (!opts.imagetools_plugin.load) {
182			throw new Error('Invalid instance of vite-imagetools. Could not find load method.');
183		}
184		const hook = opts.imagetools_plugin.load;
185		const handler = typeof hook === 'object' ? hook.handler : hook;
186		const module_info = await handler.call(opts.plugin_context, resolved_id);
187		if (!module_info) {
188			throw new Error(`Could not load ${resolved_id}`);
189		}
190		const code = typeof module_info === 'string' ? module_info : module_info.code;
191		return parseObject(code.replace('export default', '').replace(/;$/, '').trim());
192	}
