 * @returns {string}
 */
function fallback_format(meta) {
	if (meta.pages && meta.pages > 1) {
		return meta.format === 'tiff' ? 'tiff' : 'gif';
	}
	if (meta.hasAlpha) {
		return 'png';
	}
	return 'jpg';
